, "sources": [{"accessedOn": null, "documentFormat": "html", "isCurrent": true, "isPrimary": true, "language": "en", "publishedOn": null, "publisherId": null, "publisherText": "MSME Schemes 2025-26", "reference": null, "sourceId": "SCH000124-SRC001", "sourceType": "guideline", "title": "Primary source", "url": "https://pmvishwakarma.gov.in/"}, {"id": "SCH000124-SRC002", "name": "Ministry of MSME Schemes Booklet 2025-26", "url": "https://www.dcmsme.gov.in/ebook/MSMESchemebooklet2025-26.pdf", "publisherText": "Ministry of MSME Schemes Booklet 2025-26", "type": "official_booklet", "isPrimary": false}], "targetBeneficiaries": {"beneficiaryTypes": [], "businessStages": [], "description": "Eligible artisans/craftspeople in notified traditional trades under PM Vishwakarma", "enterpriseTypes": [], "specialCategories": []}}, "identity": {"acronym": null, "code": "TN124", "entityType": "scheme", "id": "SCH000124", "language": "en", "legacyCodes": [{"code": "TN124", "system": "tn_spreadsheet"}, {"code": "IN124", "system": "legacy_json"}, {"system": "mss_v3_1", "code": "MSME2526-078"}], "name": "PM Vishwakarma- Enabling Artisans & Craftspeople to scale-up their Enterprises", "shortName": null, "slug": "pm-vishwakarma-enabling-artisans-craftspeople-to-scale-up-their-enterprises", "status": "active"}, "localization": {"en": {"applicationText": "Through PM Vishwakarma implementation process", "benefitsText": "Scheme includes recognition, skill training, toolkit support, concessional collateral-free enterprise-development credit, digital incentives and marketing support. Exact current component values should follow official guidelines.", "description": "Integrated support programme for traditional artisans and craftspeople.", "eligibilityText": "Artisans and craftspeople aged 18+ working in one of the notified traditional trades can apply. Only one member per family is eligible, and specified government employees/families and recent beneficiaries of similar self-employment credit schemes are excluded.", "name": "PM Vishwakarma- Enabling Artisans & Craftspeople to scale-up their Enterprises", "objective": "Improve skills, tools, credit access, digital adoption, market linkages and enterprise scale.", "shortName": null, "summary": "Integrated support programme for traditional artisans and craftspeople."}, "hi": {"applicationText": "ऑनलाइन आवेदन जमा करने हेतु निकटतम कॉमन सर्विस सेंटर (सीएससी) पर जाएं", "benefitsText": "पीएम विश्वकर्मा प्रमाणपत्र एवं पहचान पत्र के माध्यम से कारीगरों एवं शिल्पकारों को मान्यता कौशल उन्नयन: 5-7 दिन का बुनियादी प्रशिक्षण तथा 15 दिन या अधिक का उन्नत प्रशिक्षण, ₹500 प्रतिदिन वजीफे के साथ तथा ₹1,000 परिवहन भत्ता ई-वाउचर के माध्यम से ₹15,000 तक का टूलकिट प्रोत्साहन ₹3 लाख तक के संपार्श्विक-मुक्त ''उद्यम विकास ऋण'', ₹1 लाख एवं ₹2 लाख की दो किस्तों में, क्रमशः 18 माह एवं 30 माह की अवधि हेतु, 5% की रियायती ब्याज दर पर, भारत सरकार द्वारा 8% तक ब्याज अनुदान सहित प्रति पात्र डिजिटल लेनदेन ₹1 का प्रोत्साहन, प्रतिमाह अधिकतम 100 पात्र लेनदेन तक गुणवत्ता प्रमाणन, ब्रांडिंग, ई-कॉमर्स प्लेटफॉर्म पर ऑनबोर्डिंग के रूप में विपणन सहायता", "description": "कारीगरों एवं शिल्पकारों को विश्वकर्मा के रूप में मान्यता देना, जिससे वे योजना के सभी लाभ प्राप्त करने के पात्र हों 18 व्यवसायों के कारीगर एवं शिल्पकार शामिल: बढ़ई (सुथार/बढ़ई), नाव निर्माता, अस्त्रकार, लोहार/धातु ढलाईकार, हथौड़ा एवं टूल किट निर्माता, ताला बनाने वाला, सुनार, कुम्हार, मूर्तिकार (पत्थर तराशने वाला), पत्थर तोड़ने वाला, चर्मकार/जूता कारीगर, राजमिस्त्री, टोकरी/चटाई/झाड़ू निर्माता/कॉयर बुनकर, पारंपरिक गुड़िया एवं खिलौना निर्माता, नाई, माला बनाने वाला (मालाकार), धोबी, दर्जी, मछली पकड़ने का जाल बनाने वाला", "eligibilityText": "सूचीबद्ध 18 व्यवसायों में से किसी में कार्यरत कारीगर एवं शिल्पकार", "name": "पीएम विश्वकर्मा", "objective": "कारीगरों एवं शिल्पकारों को विश्वकर्मा के रूप में मान्यता देना, जिससे वे योजना के सभी लाभ प्राप्त करने के पात्र हों 18 व्यवसायों के कारीगर एवं शिल्पकार शामिल: बढ़ई (सुथार/बढ़ई), नाव निर्माता, अस्त्रकार", "shortName": null, "summary": "कारीगरों एवं शिल्पकारों को विश्वकर्मा के रूप में मान्यता देना, जिससे वे योजना के सभी लाभ प्राप्त करने के पात्र हों 18 व्यवसायों के कारीगर एवं शिल्पकार शामिल: बढ़ई (सुथार/बढ़ई), नाव निर्माता, अस्त्रकार"}, "ta": {"applicationText": "PM Vishwakarma செயலாக்க நடைமுறை வழியாக", "benefitsText": "இத்திட்டத்தில் அங்கீகாரம், திறன் பயிற்சி, கருவித்தொகுப்பு ஆதரவு, சலுகை விகிதத்தில் அடைமானமில்லா நிறுவன மேம்பாட்டுக் கடன், இணையவழி ஊக்கத்தொகைகள் மற்றும் சந்தைப்படுத்தல் ஆதரவு ஆகியவை அடங்கும். துல்லியமான தற்போதைய கூறு மதிப்புகள் அதிகாரப்பூர்வ வழிகாட்டு நெறிமுறைகளைப் பின்பற்ற வேண்டும்.", "description": "பாரம்பரியக் கைவினைஞர்கள் மற்றும் கலைஞர்களுக்கான ஒருங்கிணைந்த ஆதரவுத் திட்டம்.", "eligibilityText": "அறிவிக்கப்பட்ட பாரம்பரியத் தொழில்களில் ஒன்றில் பணியாற்றும் 18 வயது நிரம்பிய கைவினைஞர்களும் கலைஞர்களும் விண்ணப்பிக்கலாம். ஒரு குடும்பத்திற்கு ஒரு உறுப்பினர் மட்டுமே தகுதியுடையவர்; குறிப்பிடப்பட்ட அரசு ஊழியர்கள் மற்றும் அவர்களது குடும்பங்கள், மேலும் இதுபோன்ற சுயவேலைவாய்ப்புக் கடன் திட்டங்களில் அண்மையில் பயன் பெற்றவர்கள் விலக்கப்படுகின்றனர்.", "name": "PM விஸ்வகர்மா — கைவினைஞர்கள் மற்றும் கலைஞர்கள் தங்கள் நிறுவனங்களை விரிவுபடுத்த வழிவகை செய்தல்", "objective": "திறன்கள், கருவிகள், கடன் அணுகல், இணையவழிப் பயன்பாடு, சந்தை இணைப்புகள் மற்றும் நிறுவன அளவை மேம்படுத்துதல்.", "shortName": null, "summary": "பாரம்பரியக் கைவினைஞர்கள் மற்றும் கலைஞர்களுக்கான ஒருங்கிணைந்த ஆதரவுத் திட்டம்."}}, "metadata": {"catalogVersion": "1.35.0-alpha", "createdAt": "2026-08-04T00:00:00Z", "recordStatus": "published", "revision": 29, "schemaVersion": "1.0.0", "updatedAt": "2026-10-04T13:45:56Z"}, "provenance": {"contributingSourceIds": ["SCH000124-SRC001"], "defaultSourceTier": 2, "extractedAt": "2026-08-04T00:00:00Z", "extractionMethod": "automated", "fieldSources": [{"confidence": "high", "field": "content.applicationProcess.mode", "isBackfill": true, "note": "Confirmed official portal with ''registration processes, along with multiple login portals for different user categories (applicants, CSCs, ...)'' stated directly on-site (batch